/** Build JSON body for POST /location/add and /location/edit/{id} */
export function buildOutletPayload(formData) {
  const payload = {
    name: (formData.name || "").trim(),
    phone: (formData.phone || "").trim(),
    email: (formData.email || "").trim(),
  };

  const secondary = (formData.secondary_phone || "").trim();
  if (secondary) {
    payload.secondary_phone = secondary;
  }

  return payload;
}

export function getOutletSecondaryPhone(outlet) {
  if (!outlet) return "";
  return (
    outlet.secondary_phone || outlet.phone_secondary || outlet.mobile || ""
  );
}
